list_shipping_classes.code:
import (
	"fmt"
)

resp, err := client.ShippingClasses().ListShippingClasses(ctx, map[string]any{"limit": 20}, nil)
if err != nil {
	log.Fatal(err)
}
for _, row := range resp.Map().(map[string]any)["shipping_classes"].([]any) {
	shippingClass := row.(map[string]any)
	fmt.Println(shippingClass["id"], shippingClass["name"], shippingClass["is_default"])
}

